    /** 对齐 magic_panel_bg.xml：scrim + 双描边 */
    public static Drawable panelBg(Context ctx) {
        float r16 = dp(ctx, 16);
        float r15 = dp(ctx, 15);
        int inset = Math.round(dp(ctx, 1));

        GradientDrawable fill = new GradientDrawable();
        fill.setShape(GradientDrawable.RECTANGLE);
        fill.setColor(0xF2252650);
        fill.setCornerRadius(r16);

        GradientDrawable outerStroke = new GradientDrawable();
        outerStroke.setShape(GradientDrawable.RECTANGLE);
        outerStroke.setColor(0x00000000);
        outerStroke.setCornerRadius(r16);
        outerStroke.setStroke(Math.round(dp(ctx, 1.5f)), 0x669B7ED8);

        GradientDrawable innerStroke = new GradientDrawable();
        innerStroke.setShape(GradientDrawable.RECTANGLE);
        innerStroke.setColor(0x00000000);
        innerStroke.setCornerRadius(r15);
        innerStroke.setStroke(Math.max(1, Math.round(dp(ctx, 0.5f))), 0x339B7ED8);

        Drawable[] layers = new Drawable[]{fill, outerStroke, innerStroke};
        LayerDrawable layer = new LayerDrawable(layers);
        layer.setLayerInset(2, inset, inset, inset, inset);
        return layer;
    }

