    /** 分类标题左右饰纹：线 + 菱形 + 中心点 */
    private static final class CatOrnamentDrawable extends Drawable {
        private final Paint stroke = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint fill = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Path path = new Path();

        CatOrnamentDrawable() {
            stroke.setStyle(Paint.Style.STROKE);
            stroke.setStrokeCap(Paint.Cap.ROUND);
            fill.setStyle(Paint.Style.FILL);
        }

        @Override
        public void draw(Canvas canvas) {
            Rect b = getBounds();
            if (b.isEmpty()) return;
            float sx = b.width() / 96f;
            float sy = b.height() / 24f;
            canvas.save();
            canvas.translate(b.left, b.top);
            canvas.scale(sx, sy);

            stroke.setStrokeWidth(1.4f);
            stroke.setColor(0x669B7ED8);
            // 线从视口左缘起笔，与功能行标签（同为 header/row 的 SPACE_TIGHT）左对齐
            canvas.drawLine(0f, 12f, 68f, 12f, stroke);

            fill.setColor(BRAND);
            path.reset();
            path.moveTo(72f, 12f);
            path.lineTo(80f, 6f);
            path.lineTo(88f, 12f);
            path.lineTo(80f, 18f);
            path.close();
            canvas.drawPath(path, fill);

            fill.setColor(INK);
            canvas.drawCircle(80f, 12f, 1.6f, fill);

            canvas.restore();
        }

        @Override
        public void setAlpha(int alpha) {
            stroke.setAlpha(alpha);
            fill.setAlpha(alpha);
            invalidateSelf();
        }

        @Override
        public void setColorFilter(ColorFilter colorFilter) {
            stroke.setColorFilter(colorFilter);
            fill.setColorFilter(colorFilter);
            invalidateSelf();
        }

        @Override
        public int getOpacity() {
            return PixelFormat.TRANSLUCENT;
        }

        @Override
        public int getIntrinsicWidth() {
            return -1;
        }

        @Override
        public int getIntrinsicHeight() {
            return -1;
        }
    }

    /** 折线箭头（分类 / 下拉） */
    private static final class ChevronDrawable extends Drawable {
        private final float viewport;
        private final int color;
        private final float strokeWidth;
        private final float[] pts;
        private final Paint stroke = new Paint(Paint.ANTI_ALIAS_FLAG);

        ChevronDrawable(float viewport, int color, float strokeWidth, String unusedPath) {
            this.viewport = viewport;
            this.color = color;
            this.strokeWidth = strokeWidth;
            // unusedPath kept for call-site clarity; coords encoded by viewport size
            if (viewport <= 12.5f) {
                this.pts = new float[]{2f, 4f, 6f, 8f, 10f, 4f};
            } else {
                this.pts = new float[]{6f, 9f, 12f, 15f, 18f, 9f};
            }
            stroke.setStyle(Paint.Style.STROKE);
            stroke.setStrokeCap(Paint.Cap.ROUND);
            stroke.setStrokeJoin(Paint.Join.ROUND);
        }

        @Override
        public void draw(Canvas canvas) {
            Rect b = getBounds();
            if (b.isEmpty()) return;
            float scale = Math.min(b.width(), b.height()) / viewport;
            canvas.save();
            canvas.translate(b.left + (b.width() - viewport * scale) * 0.5f,
                    b.top + (b.height() - viewport * scale) * 0.5f);
            canvas.scale(scale, scale);
            stroke.setStrokeWidth(strokeWidth);
            stroke.setColor(color);
            canvas.drawLine(pts[0], pts[1], pts[2], pts[3], stroke);
            canvas.drawLine(pts[2], pts[3], pts[4], pts[5], stroke);
            canvas.restore();
        }

        @Override
        public void setAlpha(int alpha) {
            stroke.setAlpha(alpha);
            invalidateSelf();
        }

        @Override
        public void setColorFilter(ColorFilter colorFilter) {
            stroke.setColorFilter(colorFilter);
            invalidateSelf();
        }

        @Override
        public int getOpacity() {
            return PixelFormat.TRANSLUCENT;
        }

        @Override
        public int getIntrinsicWidth() {
            return -1;
        }

        @Override
        public int getIntrinsicHeight() {
            return -1;
        }
    }

    /** Toast 成功/失败：圆环 + 勾或叉 */
    private static final class ToastStatusIconDrawable extends Drawable {
        private final int color;
        private final boolean ok;
        private final int sizePx;
        private final Paint stroke = new Paint(Paint.ANTI_ALIAS_FLAG);

        ToastStatusIconDrawable(int color, boolean ok, int sizePx) {
            this.color = color;
            this.ok = ok;
            this.sizePx = Math.max(1, sizePx);
            stroke.setStyle(Paint.Style.STROKE);
            stroke.setStrokeCap(Paint.Cap.ROUND);
            stroke.setStrokeJoin(Paint.Join.ROUND);
        }

        @Override
        public void draw(Canvas canvas) {
            Rect b = getBounds();
            if (b.isEmpty()) return;
            float scale = Math.min(b.width(), b.height()) / 24f;
            canvas.save();
            canvas.translate(b.left + (b.width() - 24f * scale) * 0.5f,
                    b.top + (b.height() - 24f * scale) * 0.5f);
            canvas.scale(scale, scale);
            stroke.setColor(color);
            stroke.setStrokeWidth(1.8f);
            canvas.drawCircle(12f, 12f, 10f, stroke);
            if (ok) {
                canvas.drawLine(7.5f, 12.5f, 10.5f, 15.5f, stroke);
                canvas.drawLine(10.5f, 15.5f, 16.5f, 8.5f, stroke);
            } else {
                canvas.drawLine(9f, 9f, 15f, 15f, stroke);
                canvas.drawLine(15f, 9f, 9f, 15f, stroke);
            }
            canvas.restore();
        }

        @Override
        public void setAlpha(int alpha) {
            stroke.setAlpha(alpha);
            invalidateSelf();
        }

        @Override
        public void setColorFilter(ColorFilter colorFilter) {
            stroke.setColorFilter(colorFilter);
            invalidateSelf();
        }

        @Override
        public int getOpacity() {
            return PixelFormat.TRANSLUCENT;
        }

        @Override
        public int getIntrinsicWidth() {
            return sizePx;
        }

        @Override
        public int getIntrinsicHeight() {
            return sizePx;
        }
    }

